import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

interface TenantBucket {
  tokens: number;
  lastRefill: number;
  tenantId: string;
}

const BUCKET_CAPACITY = 100;
const REFILL_RATE = 10; // tokens per second
const REFILL_INTERVAL_MS = 1000;

// JWT signing secret must be provided via environment; fail fast if absent.
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}

class RateLimiter {
  private buckets: Map<string, TenantBucket> = new Map();

  private computeBucketKey(tenantId: string, endpoint: string): string {
    const normalized = this.normalizeTenantId(tenantId);
    return crypto.createHash('sha256')
      .update(`${normalized}:${endpoint}`)
      .digest('hex');
  }

  private normalizeTenantId(tenantId: string): string {
    // Normalize tenant ID: trim, lowercase, remove non-alphanumeric
    return tenantId
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9\-]/g, '');
  }

  private refillBucket(bucket: TenantBucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    const tokensToAdd = Math.floor(elapsed / REFILL_INTERVAL_MS) * REFILL_RATE;
    bucket.tokens = Math.min(BUCKET_CAPACITY, bucket.tokens + tokensToAdd);
    bucket.lastRefill = now;
  }

  public tryConsume(tenantId: string, endpoint: string): boolean {
    const key = this.computeBucketKey(tenantId, endpoint);
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = {
        tokens: BUCKET_CAPACITY,
        lastRefill: Date.now(),
        tenantId: tenantId
      };
      this.buckets.set(key, bucket);
    }

    this.refillBucket(bucket);

    if (bucket.tokens > 0) {
      bucket.tokens--;
      return true;
    }
    return false;
  }

  public getBucketCount(): number {
    return this.buckets.size;
  }
}

const app = express();
const limiter = new RateLimiter();

function base64UrlDecode(input: string): Buffer {
  return Buffer.from(input, 'base64url');
}

// Verify a compact JWS (HS256) and return the decoded payload, or null if invalid.
function verifyJwt(token: string): any | null {
  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [headerB64, payloadB64, signatureB64] = parts;

  let header: any;
  try {
    header = JSON.parse(base64UrlDecode(headerB64).toString());
  } catch {
    return null;
  }

  // Only accept HMAC-SHA256; reject 'none' and other algorithms.
  if (!header || header.alg !== 'HS256' || (header.typ && header.typ !== 'JWT')) {
    return null;
  }

  const signingInput = `${headerB64}.${payloadB64}`;
  const expectedSig = crypto
    .createHmac('sha256', JWT_SECRET as string)
    .update(signingInput)
    .digest();

  let providedSig: Buffer;
  try {
    providedSig = base64UrlDecode(signatureB64);
  } catch {
    return null;
  }

  // Constant-time comparison to avoid timing attacks.
  if (
    providedSig.length !== expectedSig.length ||
    !crypto.timingSafeEqual(providedSig, expectedSig)
  ) {
    return null;
  }

  let payload: any;
  try {
    payload = JSON.parse(base64UrlDecode(payloadB64).toString());
  } catch {
    return null;
  }

  // Reject expired tokens if an exp claim is present.
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (typeof payload.exp === 'number' && payload.exp < nowSeconds) {
    return null;
  }
  if (typeof payload.nbf === 'number' && payload.nbf > nowSeconds) {
    return null;
  }

  return payload;
}

function extractTenantId(req: Request): string | null {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;

  const token = authHeader.substring(7);

  const payload = verifyJwt(token);
  if (!payload) return null;

  return typeof payload.tenant_id === 'string' ? payload.tenant_id : null;
}

function rateLimitMiddleware(req: Request, res: Response, next: NextFunction): void {
  const tenantId = extractTenantId(req);
  if (!tenantId) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const endpoint = req.path;
  const allowed = limiter.tryConsume(tenantId, endpoint);

  if (!allowed) {
    res.status(429).json({ error: 'Rate limit exceeded', retry_after: 1 });
    return;
  }

  (req as any).tenantId = tenantId;
  next();
}

app.use(express.json());
app.use(rateLimitMiddleware);

app.get('/api/v1/resources', (req: Request, res: Response) => {
  const tenantId = (req as any).tenantId;
  res.json({ tenant: tenantId, resources: [] });
});

app.post('/api/v1/resources', (req: Request, res: Response) => {
  const tenantId = (req as any).tenantId;
  res.status(201).json({ tenant: tenantId, id: crypto.randomUUID() });
});

app.get('/api/v1/health', (_req: Request, res: Response) => {
  res.json({ status: 'ok', buckets: limiter.getBucketCount() });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

export { app, RateLimiter };
